"""Serialize and Deserialize Binary Tree — preorder with explicit null markers.

Preorder plus a marker for every missing child is unambiguous, so deserialising
is a single left-to-right pass over the tokens.

Time: O(n) both ways   Space: O(n)
"""
from collections import deque

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Codec:
    def serialize(self, root) -> str:
        parts = []

        def walk(node) -> None:
            if not node:
                parts.append("#")
                return
            parts.append(str(node.val))
            walk(node.left)
            walk(node.right)

        walk(root)
        return ",".join(parts)

    def deserialize(self, data: str):
        tokens = deque(data.split(","))

        def build():
            token = tokens.popleft()
            if token == "#":
                return None
            node = TreeNode(int(token))
            node.left = build()
            node.right = build()
            return node

        return build()
